async function getConfidentialTransferWithFeeInstructionPlan(input) {
  const sourceAccount = getRequiredConfidentialTransferAccountExtension(input.sourceTokenAccount);
  const amount = BigInt(input.amount);
  assertNonNegativeAmount(amount);
  assertU64Amount(amount, "Amount");
  const transferFeeConfig = getRequiredMintExtension(input.mintAccount, "TransferFeeConfig");
  const confidentialTransferFee = getRequiredMintExtension(input.mintAccount, "ConfidentialTransferFee");
  const transferFee = getEpochTransferFee(transferFeeConfig, input.currentEpoch);
  const maximumFee = BigInt(transferFee.maximumFee);
  const { feeAmount, claimedDeltaFee, netTransferAmount } = calculateTransferWithFeeAmounts(
    amount,
    transferFee.transferFeeBasisPoints,
    maximumFee
  );
  assertU64Amount(feeAmount, "Fee amount");
  assertU64Amount(claimedDeltaFee, "Claimed delta fee");
  assertU64Amount(netTransferAmount, "Net transfer amount");
  const [transferAmountLo, transferAmountHi] = splitAmount(amount, TRANSFER_AMOUNT_LO_BIT_LENGTH);
  const [feeAmountLo, feeAmountHi] = splitAmount(feeAmount, FEE_AMOUNT_LO_BIT_LENGTH);
  const sourcePubkey = input.sourceElgamalKeypair.pubkey();
  const destinationPubkey = getDestinationElGamalPubkey(input);
  const auditorPubkey = await getAuditorElGamalPubkey(input);
  const withdrawWithheldAuthorityPubkey = getElGamalPubkeyFromAddress(confidentialTransferFee.elgamalPubkey);
  const transferAmountOpeningLo = new bundler.PedersenOpening();
  const transferAmountOpeningHi = new bundler.PedersenOpening();
  const transferAmountGroupedCiphertextLo = bundler.GroupedElGamalCiphertext3Handles.encryptWith(
    sourcePubkey,
    destinationPubkey,
    auditorPubkey,
    transferAmountLo,
    transferAmountOpeningLo
  );
  const transferAmountGroupedCiphertextHi = bundler.GroupedElGamalCiphertext3Handles.encryptWith(
    sourcePubkey,
    destinationPubkey,
    auditorPubkey,
    transferAmountHi,
    transferAmountOpeningHi
  );
  const transferAmountGroupedCiphertextLoBytes = transferAmountGroupedCiphertextLo.toBytes();
  const transferAmountGroupedCiphertextHiBytes = transferAmountGroupedCiphertextHi.toBytes();
  const transferAmountSourceCiphertextLo = transferAmountGroupedCiphertextLo.toElGamalCiphertext(0);
  const transferAmountSourceCiphertextHi = transferAmountGroupedCiphertextHi.toElGamalCiphertext(0);
  const transferAmountAuditorCiphertextLo = transferAmountGroupedCiphertextLo.toElGamalCiphertext(2).toBytes();
  const transferAmountAuditorCiphertextHi = transferAmountGroupedCiphertextHi.toElGamalCiphertext(2).toBytes();
  const currentAvailableBalance = decryptAvailableBalance(sourceAccount, input.aesKey);
  const newAvailableBalance = computeNewAvailableBalance(currentAvailableBalance, amount);
  assertU64Amount(newAvailableBalance, "New available balance");
  const newAvailableBalanceOpening = new bundler.PedersenOpening();
  const newAvailableBalanceCommitment = bundler.PedersenCommitment.from(newAvailableBalance, newAvailableBalanceOpening);
  const newAvailableBalanceCiphertext = parseElGamalCiphertext(sourceAccount.availableBalance).subtract(
    bundler.ElGamalCiphertext.combineLoHi(
      transferAmountSourceCiphertextLo,
      transferAmountSourceCiphertextHi,
      Number(TRANSFER_AMOUNT_LO_BIT_LENGTH)
    )
  );
  const equalityProofData = new bundler.CiphertextCommitmentEqualityProofData(
    input.sourceElgamalKeypair,
    newAvailableBalanceCiphertext,
    newAvailableBalanceCommitment,
    newAvailableBalanceOpening,
    newAvailableBalance
  );
  const transferAmountCiphertextValidityProofData = new bundler.BatchedGroupedCiphertext3HandlesValidityProofData(
    sourcePubkey,
    destinationPubkey,
    auditorPubkey,
    transferAmountGroupedCiphertextLo,
    transferAmountGroupedCiphertextHi,
    transferAmountLo,
    transferAmountHi,
    transferAmountOpeningLo,
    transferAmountOpeningHi
  );
  const transferAmountCommitmentLo = bundler.PedersenCommitment.fromBytes(
    transferAmountGroupedCiphertextLoBytes.slice(0, 32)
  );
  const transferAmountCommitmentHi = bundler.PedersenCommitment.fromBytes(
    transferAmountGroupedCiphertextHiBytes.slice(0, 32)
  );
  const combinedTransferAmountCommitment = bundler.PedersenCommitment.combineLoHi(
    transferAmountCommitmentLo,
    transferAmountCommitmentHi,
    Number(TRANSFER_AMOUNT_LO_BIT_LENGTH)
  );
  const combinedTransferAmountOpening = bundler.PedersenOpening.combineLoHi(
    transferAmountOpeningLo,
    transferAmountOpeningHi,
    Number(TRANSFER_AMOUNT_LO_BIT_LENGTH)
  );
  const feeOpeningLo = new bundler.PedersenOpening();
  const feeOpeningHi = new bundler.PedersenOpening();
  const feeGroupedCiphertextLo = bundler.GroupedElGamalCiphertext2Handles.encryptWith(
    destinationPubkey,
    withdrawWithheldAuthorityPubkey,
    feeAmountLo,
    feeOpeningLo
  );
  const feeGroupedCiphertextHi = bundler.GroupedElGamalCiphertext2Handles.encryptWith(
    destinationPubkey,
    withdrawWithheldAuthorityPubkey,
    feeAmountHi,
    feeOpeningHi
  );
  const feeGroupedCiphertextLoBytes = feeGroupedCiphertextLo.toBytes();
  const feeGroupedCiphertextHiBytes = feeGroupedCiphertextHi.toBytes();
  const feeCommitmentLo = bundler.PedersenCommitment.fromBytes(feeGroupedCiphertextLoBytes.slice(0, 32));
  const feeCommitmentHi = bundler.PedersenCommitment.fromBytes(feeGroupedCiphertextHiBytes.slice(0, 32));
  const combinedFeeCommitment = bundler.PedersenCommitment.combineLoHi(
    feeCommitmentLo,
    feeCommitmentHi,
    Number(FEE_AMOUNT_LO_BIT_LENGTH)
  );
  const combinedFeeOpening = bundler.PedersenOpening.combineLoHi(
    feeOpeningLo,
    feeOpeningHi,
    Number(FEE_AMOUNT_LO_BIT_LENGTH)
  );
  const netTransferAmountCommitment = combinedTransferAmountCommitment.subtract(combinedFeeCommitment);
  const netTransferAmountOpening = combinedTransferAmountOpening.subtract(combinedFeeOpening);
  const claimedOpening = new bundler.PedersenOpening();
  const claimedCommitment = bundler.PedersenCommitment.from(claimedDeltaFee, claimedOpening);
  const deltaCommitment = combinedFeeCommitment.multiplyByU64(MAX_FEE_BASIS_POINTS).subtract(combinedTransferAmountCommitment.multiplyByU64(BigInt(transferFee.transferFeeBasisPoints)));
  const deltaOpening = combinedFeeOpening.multiplyByU64(MAX_FEE_BASIS_POINTS).subtract(combinedTransferAmountOpening.multiplyByU64(BigInt(transferFee.transferFeeBasisPoints)));
  const percentageWithCapProofData = new bundler.PercentageWithCapProofData(
    combinedFeeCommitment,
    combinedFeeOpening,
    feeAmount,
    deltaCommitment,
    deltaOpening,
    claimedDeltaFee,
    claimedCommitment,
    claimedOpening,
    maximumFee
  );
  const feeCiphertextValidityProofData = new bundler.BatchedGroupedCiphertext2HandlesValidityProofData(
    destinationPubkey,
    withdrawWithheldAuthorityPubkey,
    feeGroupedCiphertextLo,
    feeGroupedCiphertextHi,
    feeAmountLo,
    feeAmountHi,
    feeOpeningLo,
    feeOpeningHi
  );
  const zeroOpening = bundler.PedersenOpening.zero();
  const maxFeeBasisPointsSubOneCommitment = bundler.PedersenCommitment.from(MAX_FEE_BASIS_POINTS_SUB_ONE, zeroOpening);
  const claimedComplementCommitment = maxFeeBasisPointsSubOneCommitment.subtract(claimedCommitment);
  const claimedComplementOpening = zeroOpening.subtract(claimedOpening);
  const deltaFeeComplement = MAX_FEE_BASIS_POINTS_SUB_ONE - claimedDeltaFee;
  if (deltaFeeComplement < 0n) {
    throw new Error("Claimed delta fee exceeds maximum range.");
  }
  const rangeProofData = new bundler.BatchedRangeProofU256Data(
    [
      newAvailableBalanceCommitment,
      transferAmountCommitmentLo,
      transferAmountCommitmentHi,
      claimedCommitment,
      claimedComplementCommitment,
      feeCommitmentLo,
      feeCommitmentHi,
      netTransferAmountCommitment
    ],
    new BigUint64Array([
      newAvailableBalance,
      transferAmountLo,
      transferAmountHi,
      claimedDeltaFee,
      deltaFeeComplement,
      feeAmountLo,
      feeAmountHi,
      netTransferAmount
    ]),
    Uint8Array.from([
      REMAINING_BALANCE_BIT_LENGTH,
      Number(TRANSFER_AMOUNT_LO_BIT_LENGTH),
      Number(TRANSFER_AMOUNT_HI_BIT_LENGTH),
      DELTA_BIT_LENGTH,
      DELTA_BIT_LENGTH,
      Number(FEE_AMOUNT_LO_BIT_LENGTH),
      Number(FEE_AMOUNT_HI_BIT_LENGTH),
      NET_TRANSFER_AMOUNT_BIT_LENGTH
    ]),
    [
      newAvailableBalanceOpening,
      transferAmountOpeningLo,
      transferAmountOpeningHi,
      claimedOpening,
      claimedComplementOpening,
      feeOpeningLo,
      feeOpeningHi,
      netTransferAmountOpening
    ]
  );
  const [
    equalityProofPlan,
    transferAmountCiphertextValidityProofPlan,
    percentageWithCapProofPlan,
    feeCiphertextValidityProofPlan,
    rangeProofPlan
  ] = await Promise.all([
    buildContextStateProofPlan(
      equalityProofData.toBytes(),
      zkElgamalProof.verifyCiphertextCommitmentEquality,
      input.payer,
      input.rpc
    ),
    buildContextStateProofPlan(
      transferAmountCiphertextValidityProofData.toBytes(),
      zkElgamalProof.verifyBatchedGroupedCiphertext3HandlesValidity,
      input.payer,
      input.rpc
    ),
    buildContextStateProofPlan(
      percentageWithCapProofData.toBytes(),
      zkElgamalProof.verifyPercentageWithCap,
      input.payer,
      input.rpc
    ),
    buildContextStateProofPlan(
      feeCiphertextValidityProofData.toBytes(),
      zkElgamalProof.verifyBatchedGroupedCiphertext2HandlesValidity,
      input.payer,
      input.rpc
    ),
    buildContextStateProofPlan(
      rangeProofData.toBytes(),
      zkElgamalProof.verifyBatchedRangeProofU256,
      input.payer,
      input.rpc,
      input.payer,
      input.recordPayer ?? input.payer,
      input.recordAuthority,
      input.recordRentReceiver
    )
  ]);
  return kit.sequentialInstructionPlan([
    kit.parallelInstructionPlan([
      equalityProofPlan.setup,
      transferAmountCiphertextValidityProofPlan.setup,
      percentageWithCapProofPlan.setup,
      feeCiphertextValidityProofPlan.setup,
      rangeProofPlan.setup
    ]),
    getConfidentialTransferWithFeeInstruction(
      {
        sourceToken: input.sourceToken,
        mint: input.mint,
        destinationToken: input.destinationToken,
        equalityRecord: equalityProofPlan.address,
        transferAmountCiphertextValidityRecord: transferAmountCiphertextValidityProofPlan.address,
        feeSigmaRecord: percentageWithCapProofPlan.address,
        feeCiphertextValidityRecord: feeCiphertextValidityProofPlan.address,
        rangeRecord: rangeProofPlan.address,
        authority: input.authority,
        newSourceDecryptableAvailableBalance: input.aesKey.encrypt(newAvailableBalance).toBytes(),
        transferAmountAuditorCiphertextLo,
        transferAmountAuditorCiphertextHi,
        equalityProofInstructionOffset: 0,
        transferAmountCiphertextValidityProofInstructionOffset: 0,
        feeSigmaProofInstructionOffset: 0,
        feeCiphertextValidityProofInstructionOffset: 0,
        rangeProofInstructionOffset: 0,
        multiSigners: input.multiSigners
      },
      { programAddress: input.programAddress }
    ),
    kit.parallelInstructionPlan([
      equalityProofPlan.cleanup,
      transferAmountCiphertextValidityProofPlan.cleanup,
      percentageWithCapProofPlan.cleanup,
      feeCiphertextValidityProofPlan.cleanup,
      rangeProofPlan.cleanup
    ])
  ]);
}
function assertMintBurnAmount(amount, label) {
  if (amount <= 0n) {
    throw new Error(`${label} amount must be positive.`);
  }
  if (amount > MAX_MINT_BURN_AMOUNT) {
    throw new Error(
      `${label} amount exceeds the maximum confidential mint/burn amount (2^48 - 1 = ${MAX_MINT_BURN_AMOUNT}).`
    );
  }
}
async function buildConfidentialMintProofPlan(input, record) {
  const mintBurnExtension = getRequiredMintExtension(input.mintAccount, "ConfidentialMintBurn");
  const amount = BigInt(input.amount);
  assertMintBurnAmount(amount, "Mint");
  const currentSupply = decryptConfidentialMintBurnSupply({
    mintAccount: input.mintAccount,
    supplyElgamalKeypair: input.supplyElgamalKeypair,
    supplyAesKey: input.supplyAesKey
  });
  const newSupply = currentSupply + amount;
  assertU64Amount(newSupply, "New supply after mint");
  const [amountLo, amountHi] = splitAmount(amount, MINT_BURN_AMOUNT_LO_BIT_LENGTH);
  const destinationPubkey = getElGamalPubkeyFromAddress(
    getRequiredConfidentialTransferAccountExtension(input.destinationTokenAccount).elgamalPubkey
  );
  const supplyPubkey = input.supplyElgamalKeypair.pubkey();
  const auditorPubkey = await getAuditorElGamalPubkey(input);
  const openingLo = new bundler.PedersenOpening();
  const openingHi = new bundler.PedersenOpening();
  const groupedCiphertextLo = bundler.GroupedElGamalCiphertext3Handles.encryptWith(
    destinationPubkey,
    supplyPubkey,
    auditorPubkey,
    amountLo,
    openingLo
  );
  const groupedCiphertextHi = bundler.GroupedElGamalCiphertext3Handles.encryptWith(
    destinationPubkey,
    supplyPubkey,
    auditorPubkey,
    amountHi,
    openingHi
  );
  const groupedCiphertextLoBytes = groupedCiphertextLo.toBytes();
  const groupedCiphertextHiBytes = groupedCiphertextHi.toBytes();
  const supplyCiphertextLo = groupedCiphertextLo.toElGamalCiphertext(1);
  const supplyCiphertextHi = groupedCiphertextHi.toElGamalCiphertext(1);
  const mintAmountAuditorCiphertextLo = groupedCiphertextLo.toElGamalCiphertext(2).toBytes();
  const mintAmountAuditorCiphertextHi = groupedCiphertextHi.toElGamalCiphertext(2).toBytes();
  const newSupplyCiphertext = parseElGamalCiphertext(mintBurnExtension.confidentialSupply).add(
    bundler.ElGamalCiphertext.combineLoHi(supplyCiphertextLo, supplyCiphertextHi, Number(MINT_BURN_AMOUNT_LO_BIT_LENGTH))
  );
  const newSupplyOpening = new bundler.PedersenOpening();
  const newSupplyCommitment = bundler.PedersenCommitment.from(newSupply, newSupplyOpening);
  const equalityProofData = new bundler.CiphertextCommitmentEqualityProofData(
    input.supplyElgamalKeypair,
    newSupplyCiphertext,
    newSupplyCommitment,
    newSupplyOpening,
    newSupply
  );
  const ciphertextValidityProofData = new bundler.BatchedGroupedCiphertext3HandlesValidityProofData(
    destinationPubkey,
    supplyPubkey,
    auditorPubkey,
    groupedCiphertextLo,
    groupedCiphertextHi,
    amountLo,
    amountHi,
    openingLo,
    openingHi
  );
  const commitmentLo = bundler.PedersenCommitment.fromBytes(groupedCiphertextLoBytes.slice(0, 32));
  const commitmentHi = bundler.PedersenCommitment.fromBytes(groupedCiphertextHiBytes.slice(0, 32));
  const paddingOpening = new bundler.PedersenOpening();
  const paddingCommitment = bundler.PedersenCommitment.from(0n, paddingOpening);
  const rangeProofData = new bundler.BatchedRangeProofU128Data(
    [newSupplyCommitment, commitmentLo, commitmentHi, paddingCommitment],
    new BigUint64Array([newSupply, amountLo, amountHi, 0n]),
    Uint8Array.from([
      REMAINING_BALANCE_BIT_LENGTH,
      Number(MINT_BURN_AMOUNT_LO_BIT_LENGTH),
      Number(MINT_BURN_AMOUNT_HI_BIT_LENGTH),
      RANGE_PROOF_PADDING_BIT_LENGTH
    ]),
    [newSupplyOpening, openingLo, openingHi, paddingOpening]
  );
  const [equalityProofPlan, ciphertextValidityProofPlan, rangeProofPlan] = await Promise.all([
    buildContextStateProofPlan(
      equalityProofData.toBytes(),
      zkElgamalProof.verifyCiphertextCommitmentEquality,
      input.payer,
      input.rpc
    ),
    buildContextStateProofPlan(
      ciphertextValidityProofData.toBytes(),
      zkElgamalProof.verifyBatchedGroupedCiphertext3HandlesValidity,
      input.payer,
      input.rpc
    ),
    buildContextStateProofPlan(
      rangeProofData.toBytes(),
      zkElgamalProof.verifyBatchedRangeProofU128,
      input.payer,
      input.rpc,
      input.payer,
      record ? record.recordPayer ?? input.payer : void 0,
      record?.recordAuthority,
      record?.recordRentReceiver
    )
  ]);
  return {
    setup: kit.parallelInstructionPlan([
      equalityProofPlan.setup,
      ciphertextValidityProofPlan.setup,
      rangeProofPlan.setup
    ]),
    cleanup: kit.parallelInstructionPlan([
      equalityProofPlan.cleanup,
      ciphertextValidityProofPlan.cleanup,
      rangeProofPlan.cleanup
    ]),
    mintArgs: {
      token: input.token,
      mint: input.mint,
      equalityRecord: equalityProofPlan.address,
      ciphertextValidityRecord: ciphertextValidityProofPlan.address,
      rangeRecord: rangeProofPlan.address,
      authority: input.authority,
      newDecryptableSupply: input.supplyAesKey.encrypt(newSupply).toBytes(),
      mintAmountAuditorCiphertextLo,
      mintAmountAuditorCiphertextHi,
      equalityProofInstructionOffset: 0,
      ciphertextValidityProofInstructionOffset: 0,
      rangeProofInstructionOffset: 0,
      multiSigners: input.multiSigners
    }
  };
}
async function getConfidentialMintInstructionPlan(input) {
  const { setup, cleanup, mintArgs } = await buildConfidentialMintProofPlan(input);
  return kit.sequentialInstructionPlan([
    setup,
    getConfidentialMintInstruction(mintArgs, { programAddress: input.programAddress }),
    cleanup
  ]);
}
async function getConfidentialMintWithRecordInstructionPlan(input) {
  const { setup, cleanup, mintArgs } = await buildConfidentialMintProofPlan(input, input);
  return kit.sequentialInstructionPlan([
    setup,
    getConfidentialMintInstruction(mintArgs, { programAddress: input.programAddress }),
    cleanup
  ]);
}
async function buildConfidentialBurnProofPlan(input, record) {
  const sourceAccount = getRequiredConfidentialTransferAccountExtension(input.sourceTokenAccount);
  const mintBurnExtension = getRequiredMintExtension(input.mintAccount, "ConfidentialMintBurn");
  const amount = BigInt(input.amount);
  assertMintBurnAmount(amount, "Burn");
  const currentAvailableBalance = decryptAvailableBalance(sourceAccount, input.aesKey);
  const remainingBalance = computeNewAvailableBalance(currentAvailableBalance, amount);
  const [amountLo, amountHi] = splitAmount(amount, MINT_BURN_AMOUNT_LO_BIT_LENGTH);
  const sourcePubkey = input.sourceElgamalKeypair.pubkey();
  const supplyPubkey = getElGamalPubkeyFromAddress(mintBurnExtension.supplyElgamalPubkey);
  const auditorPubkey = await getAuditorElGamalPubkey(input);
  const openingLo = new bundler.PedersenOpening();
  const openingHi = new bundler.PedersenOpening();
  const groupedCiphertextLo = bundler.GroupedElGamalCiphertext3Handles.encryptWith(
    sourcePubkey,
    supplyPubkey,
    auditorPubkey,
    amountLo,
    openingLo
  );
  const groupedCiphertextHi = bundler.GroupedElGamalCiphertext3Handles.encryptWith(
    sourcePubkey,
    supplyPubkey,
    auditorPubkey,
    amountHi,
    openingHi
  );
  const groupedCiphertextLoBytes = groupedCiphertextLo.toBytes();
  const groupedCiphertextHiBytes = groupedCiphertextHi.toBytes();
  const sourceCiphertextLo = groupedCiphertextLo.toElGamalCiphertext(0);
  const sourceCiphertextHi = groupedCiphertextHi.toElGamalCiphertext(0);
  const burnAmountAuditorCiphertextLo = groupedCiphertextLo.toElGamalCiphertext(2).toBytes();
  const burnAmountAuditorCiphertextHi = groupedCiphertextHi.toElGamalCiphertext(2).toBytes();
  const newAvailableBalanceCiphertext = parseElGamalCiphertext(sourceAccount.availableBalance).subtract(
    bundler.ElGamalCiphertext.combineLoHi(sourceCiphertextLo, sourceCiphertextHi, Number(MINT_BURN_AMOUNT_LO_BIT_LENGTH))
  );
  const newAvailableBalanceOpening = new bundler.PedersenOpening();
  const newAvailableBalanceCommitment = bundler.PedersenCommitment.from(remainingBalance, newAvailableBalanceOpening);
  const equalityProofData = new bundler.CiphertextCommitmentEqualityProofData(
    input.sourceElgamalKeypair,
    newAvailableBalanceCiphertext,
    newAvailableBalanceCommitment,
    newAvailableBalanceOpening,
    remainingBalance
  );
  const ciphertextValidityProofData = new bundler.BatchedGroupedCiphertext3HandlesValidityProofData(
    sourcePubkey,
    supplyPubkey,
    auditorPubkey,
    groupedCiphertextLo,
    groupedCiphertextHi,
    amountLo,
    amountHi,
    openingLo,
    openingHi
  );
  const commitmentLo = bundler.PedersenCommitment.fromBytes(groupedCiphertextLoBytes.slice(0, 32));
  const commitmentHi = bundler.PedersenCommitment.fromBytes(groupedCiphertextHiBytes.slice(0, 32));
  const paddingOpening = new bundler.PedersenOpening();
  const paddingCommitment = bundler.PedersenCommitment.from(0n, paddingOpening);
  const rangeProofData = new bundler.BatchedRangeProofU128Data(
    [newAvailableBalanceCommitment, commitmentLo, commitmentHi, paddingCommitment],
    new BigUint64Array([remainingBalance, amountLo, amountHi, 0n]),
    Uint8Array.from([
      REMAINING_BALANCE_BIT_LENGTH,
      Number(MINT_BURN_AMOUNT_LO_BIT_LENGTH),
      Number(MINT_BURN_AMOUNT_HI_BIT_LENGTH),
      RANGE_PROOF_PADDING_BIT_LENGTH
    ]),
    [newAvailableBalanceOpening, openingLo, openingHi, paddingOpening]
  );
  const [equalityProofPlan, ciphertextValidityProofPlan, rangeProofPlan] = await Promise.all([
    buildContextStateProofPlan(
      equalityProofData.toBytes(),
      zkElgamalProof.verifyCiphertextCommitmentEquality,
      input.payer,
      input.rpc
    ),
    buildContextStateProofPlan(
      ciphertextValidityProofData.toBytes(),
      zkElgamalProof.verifyBatchedGroupedCiphertext3HandlesValidity,
      input.payer,
      input.rpc
    ),
    buildContextStateProofPlan(
      rangeProofData.toBytes(),
      zkElgamalProof.verifyBatchedRangeProofU128,
      input.payer,
      input.rpc,
      input.payer,
      record ? record.recordPayer ?? input.payer : void 0,
      record?.recordAuthority,
      record?.recordRentReceiver
    )
  ]);
  return {
    setup: kit.parallelInstructionPlan([
      equalityProofPlan.setup,
      ciphertextValidityProofPlan.setup,
      rangeProofPlan.setup
    ]),
    cleanup: kit.parallelInstructionPlan([
      equalityProofPlan.cleanup,
      ciphertextValidityProofPlan.cleanup,
      rangeProofPlan.cleanup
    ]),
    // Arguments common to both burn instruction variants. The account owner
    // (`authority`) always signs; the variant-specific signer field
    // (`multiSigners` / `permissionedBurnAuthority`) is added by the caller.
    burnArgs: {
      token: input.token,
      mint: input.mint,
      equalityRecord: equalityProofPlan.address,
      ciphertextValidityRecord: ciphertextValidityProofPlan.address,
      rangeRecord: rangeProofPlan.address,
      authority: input.authority,
      newDecryptableAvailableBalance: input.aesKey.encrypt(remainingBalance).toBytes(),
      burnAmountAuditorCiphertextLo,
      burnAmountAuditorCiphertextHi,
      equalityProofInstructionOffset: 0,
      ciphertextValidityProofInstructionOffset: 0,
      rangeProofInstructionOffset: 0
    }
  };
}
