function getUpdateConfidentialMintBurnDecryptableSupplyInstructionFromSupply(input) {
  const supply = BigInt(input.supply);
  assertU64Amount(supply, "Supply");
  return getUpdateConfidentialMintBurnDecryptableSupplyInstruction(
    {
      mint: input.mint,
      authority: input.authority,
      newDecryptableSupply: input.supplyAesKey.encrypt(supply).toBytes(),
      multiSigners: input.multiSigners
    },
    { programAddress: input.programAddress }
  );
}
async function signDerivationMessage(signer, message) {
  const [signatures] = await signer.signMessages([kit.createSignableMessage(message)]);
  const signature = signatures?.[signer.address];
  if (signature == null) {
    throw new Error(`Signer ${signer.address} did not return a signature`);
  }
  return new Uint8Array(signature);
}
function decodeConfidentialKeys(keys) {
  const elgamal = keys.elgamal();
  const secretKey = new Uint8Array(elgamal.secret().toBytes());
  const elgamalPubkey = kit.getAddressDecoder().decode(new Uint8Array(elgamal.pubkey().toBytes()));
  const aeKey = new Uint8Array(keys.ae().toBytes());
  return { aeKey, elgamalKeypair: { elgamalPubkey, secretKey } };
}
function assertSeedPresent(publicSeed, caller) {
  if (publicSeed == null) {
    throw new Error(
      `${caller} requires an explicit publicSeed; for the standard wallet-level keys use deriveConfidentialKeys`
    );
  }
}
function ownerMintSeed(owner, mint) {
  return kit.getTupleEncoder([kit.getAddressEncoder(), kit.getAddressEncoder()]).encode([owner, mint]);
}
async function deriveConfidentialKeys({
  signer
}) {
  const message = bundler.ConfidentialKeys.signerMessage();
  const signature = await signDerivationMessage(signer, message);
  return decodeConfidentialKeys(bundler.ConfidentialKeys.fromSignature(signature));
}
async function deriveElGamalKeypairWithSeed({
  signer,
  publicSeed
}) {
  assertSeedPresent(publicSeed, "deriveElGamalKeypairWithSeed");
  const message = bundler.ConfidentialKeys.signerMessageWithSeed(new Uint8Array(publicSeed));
  const signature = await signDerivationMessage(signer, message);
  return decodeConfidentialKeys(bundler.ConfidentialKeys.fromSignature(signature)).elgamalKeypair;
}
async function deriveAeKeyWithSeed({
  signer,
  publicSeed
}) {
  assertSeedPresent(publicSeed, "deriveAeKeyWithSeed");
  const message = bundler.ConfidentialKeys.signerMessageWithSeed(new Uint8Array(publicSeed));
  const signature = await signDerivationMessage(signer, message);
  return decodeConfidentialKeys(bundler.ConfidentialKeys.fromSignature(signature)).aeKey;
}
async function deriveElGamalKeypairForOwnerMint({
  signer,
  owner,
  mint
}) {
  return await deriveElGamalKeypairWithSeed({ publicSeed: ownerMintSeed(owner, mint), signer });
}
async function deriveAeKeyForOwnerMint({
  signer,
  owner,
  mint
}) {
  return await deriveAeKeyWithSeed({ publicSeed: ownerMintSeed(owner, mint), signer });
}

